-- English framework-owned copy revalidation. No reopening of completed appearance/theme tasks.
CREATE TABLE tower_theme_build_reviews(id TEXT PRIMARY KEY,extension_id TEXT NOT NULL UNIQUE REFERENCES tower_autonomy_extensions(id),artifact_id TEXT NOT NULL REFERENCES tower_theme_artifacts(id),cycle_id TEXT NOT NULL REFERENCES tower_autonomy_cycles(id),generation_id TEXT NOT NULL,appearance_revision INTEGER NOT NULL,original_budget_micro INTEGER NOT NULL,source_build_hash TEXT NOT NULL,target_build_hash TEXT NOT NULL CHECK(length(target_build_hash)=64 AND target_build_hash NOT GLOB '*[^0-9a-f]*' AND target_build_hash!=source_build_hash),content_revision TEXT NOT NULL CHECK(content_revision='english-copy-v1'),locale TEXT NOT NULL DEFAULT 'en' CHECK(locale='en'),starts_at TEXT NOT NULL,ends_at TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('render-0','render-1','render-2','render-3','verify','audit','selfreview','publish','complete','blocked')),step_seq INTEGER NOT NULL DEFAULT 0,lease_until TEXT,evidence_json TEXT CHECK(evidence_json IS NULL OR json_valid(evidence_json)),audit_json TEXT CHECK(audit_json IS NULL OR json_valid(audit_json)),review_json TEXT CHECK(review_json IS NULL OR json_valid(review_json)),outcome TEXT NOT NULL DEFAULT 'pending' CHECK(outcome IN ('pending','pass','blocked')),error_code TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE tower_theme_build_acceptances(review_id TEXT PRIMARY KEY REFERENCES tower_theme_build_reviews(id),extension_id TEXT NOT NULL REFERENCES tower_autonomy_extensions(id),artifact_id TEXT NOT NULL REFERENCES tower_theme_artifacts(id),target_build_hash TEXT NOT NULL,manifest_hash TEXT NOT NULL,generation_id TEXT NOT NULL,appearance_revision INTEGER NOT NULL,created_at TEXT NOT NULL,UNIQUE(artifact_id,target_build_hash));
CREATE VIEW tower_theme_build_source AS SELECT e.*,a.renderer_build_hash AS source_build_hash,a.sha256 AS manifest_hash FROM tower_autonomy_extensions e JOIN tower_theme_artifacts a ON a.id=e.artifact_id AND a.extension_id=e.id AND a.repair=e.repair JOIN tower_theme_current t ON t.extension_id=e.id AND t.artifact_id=a.id JOIN tower_autonomy_current p ON p.cycle_id=e.cycle_id AND p.generation_id=e.generation_id AND p.revision=e.appearance_revision JOIN tower_autonomy_cycles c ON c.id=e.cycle_id AND c.state='complete' AND c.outcome='pass' AND c.budget_micro=e.original_budget_micro JOIN tower_autonomy_authorizations z ON z.cycle_id=c.id AND z.kind='appearance' AND z.budget_micro=c.budget_micro JOIN tower_autonomy_task_anchors k ON k.cycle_id=c.id AND k.anchor='appearance:halloween:2026' WHERE e.state='complete' AND e.outcome='pass' AND json_extract(e.audit_json,'$.verdict')='PASS' AND json_extract(e.audit_json,'$.manifestHash')=a.sha256 AND json_extract(e.evidence_json,'$.verified')=1 AND json_extract(e.evidence_json,'$.rendererBuildHash')=a.renderer_build_hash AND json_extract(c.audit_json,'$.verdict')='PASS' AND json_extract(c.evidence_json,'$.verified')=1 AND json_extract(c.evidence_json,'$.generation')=p.generation_id AND t.generation_id=p.generation_id AND t.appearance_revision=p.revision AND t.starts_at=e.starts_at AND t.ends_at=e.ends_at AND p.starts_at=e.starts_at AND p.ends_at=e.ends_at AND EXISTS(SELECT 1 FROM tower_autonomy_calls q WHERE q.id=json_extract(e.audit_json,'$.callId') AND q.state='received' AND q.cycle_id=e.cycle_id AND q.purpose='lobby-theme-v1:audit') AND EXISTS(SELECT 1 FROM tower_autonomy_calls q WHERE q.id=json_extract(c.audit_json,'$.callId') AND q.state='received' AND q.cycle_id=c.id AND q.purpose='independent-task-audit');
CREATE TRIGGER tower_theme_build_review_authority BEFORE INSERT ON tower_theme_build_reviews BEGIN
 SELECT CASE WHEN NEW.id=NEW.extension_id||':english-copy-v1' AND NEW.state='render-0' AND NEW.step_seq=0 AND NEW.lease_until IS NULL AND NEW.evidence_json IS NULL AND NEW.audit_json IS NULL AND NEW.review_json IS NULL AND NEW.outcome='pending' AND EXISTS(SELECT 1 FROM tower_theme_build_source s WHERE s.id=NEW.extension_id AND s.artifact_id=NEW.artifact_id AND s.cycle_id=NEW.cycle_id AND s.generation_id=NEW.generation_id AND s.appearance_revision=NEW.appearance_revision AND s.original_budget_micro=NEW.original_budget_micro AND s.source_build_hash=NEW.source_build_hash AND s.starts_at=NEW.starts_at AND s.ends_at=NEW.ends_at AND s.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND s.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND s.original_budget_micro<=(SELECT task_limit_micro FROM tower_autonomy_mandate WHERE id=1)) AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls WHERE cycle_id=NEW.cycle_id AND state IN ('unknown','dispatching')) AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE cycle_id=NEW.cycle_id)+800000<=NEW.original_budget_micro AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE billing_day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)))+800000<=(SELECT daily_limit_micro FROM tower_autonomy_mandate WHERE id=1) AND EXISTS(SELECT 1 FROM tower_autonomy_events v WHERE v.id=NEW.id||':authorized' AND v.kind='lobby-build-authorized' AND v.cycle_id=NEW.cycle_id AND v.created_at=NEW.created_at AND json_extract(v.detail_json,'$.targetBuildHash')=NEW.target_build_hash AND json_extract(v.detail_json,'$.contentRevision')='english-copy-v1') THEN 1 ELSE RAISE(ABORT,'theme_build_authority') END;
END;
CREATE TRIGGER tower_theme_build_review_binding BEFORE UPDATE ON tower_theme_build_reviews WHEN NEW.id!=OLD.id OR NEW.extension_id!=OLD.extension_id OR NEW.artifact_id!=OLD.artifact_id OR NEW.cycle_id!=OLD.cycle_id OR NEW.generation_id!=OLD.generation_id OR NEW.appearance_revision!=OLD.appearance_revision OR NEW.original_budget_micro!=OLD.original_budget_micro OR NEW.source_build_hash!=OLD.source_build_hash OR NEW.target_build_hash!=OLD.target_build_hash OR NEW.content_revision!=OLD.content_revision OR NEW.locale!=OLD.locale OR NEW.starts_at!=OLD.starts_at OR NEW.ends_at!=OLD.ends_at OR NEW.created_at!=OLD.created_at OR OLD.state IN ('complete','blocked') OR (OLD.evidence_json IS NOT NULL AND NEW.evidence_json IS NOT OLD.evidence_json) OR (OLD.audit_json IS NOT NULL AND NEW.audit_json IS NOT OLD.audit_json) OR (OLD.review_json IS NOT NULL AND NEW.review_json IS NOT OLD.review_json) BEGIN SELECT RAISE(ABORT,'theme_build_immutable'); END;
CREATE TRIGGER tower_theme_build_review_transition BEFORE UPDATE ON tower_theme_build_reviews WHEN NEW.state!=OLD.state BEGIN
 SELECT CASE WHEN NEW.step_seq=OLD.step_seq+1 AND NEW.lease_until IS NULL AND (NEW.state IN ('selfreview','blocked') OR (OLD.state='render-0' AND NEW.state='render-1') OR (OLD.state='render-1' AND NEW.state='render-2') OR (OLD.state='render-2' AND NEW.state='render-3') OR (OLD.state='render-3' AND NEW.state='verify') OR (OLD.state='verify' AND NEW.state='audit') OR (OLD.state='selfreview' AND NEW.state='publish' AND NEW.outcome='pass') OR (OLD.state='publish' AND NEW.state='complete' AND EXISTS(SELECT 1 FROM tower_theme_build_acceptances WHERE review_id=OLD.id))) AND (NEW.state IN ('selfreview','blocked') OR (OLD.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND EXISTS(SELECT 1 FROM tower_theme_build_source s WHERE s.id=NEW.extension_id AND s.artifact_id=NEW.artifact_id AND s.cycle_id=NEW.cycle_id AND s.generation_id=NEW.generation_id AND s.appearance_revision=NEW.appearance_revision AND s.original_budget_micro=NEW.original_budget_micro AND s.source_build_hash=NEW.source_build_hash AND s.starts_at=NEW.starts_at AND s.ends_at=NEW.ends_at AND s.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND s.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND s.original_budget_micro<=(SELECT task_limit_micro FROM tower_autonomy_mandate WHERE id=1)))) THEN 1 ELSE RAISE(ABORT,'theme_build_transition') END;
END;
CREATE TRIGGER tower_theme_build_call_scope BEFORE INSERT ON tower_autonomy_calls WHEN NEW.purpose LIKE 'lobby-build-v1:%' BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tower_theme_build_reviews r WHERE r.cycle_id=NEW.cycle_id AND r.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND NEW.step_key=r.cycle_id||':'||r.step_seq||':lobby-build-v1:'||r.id||':'||r.state||CASE WHEN NEW.purpose LIKE '%:input-token-count' THEN ':count' ELSE '' END AND (NEW.purpose='lobby-build-v1:'||r.id||':'||r.state OR NEW.purpose='lobby-build-v1:'||r.id||':'||r.state||':input-token-count') AND ((r.state='selfreview' AND NEW.model='muse-spark-1.3') OR (EXISTS(SELECT 1 FROM tower_theme_build_source s WHERE s.id=r.extension_id AND s.artifact_id=r.artifact_id AND s.cycle_id=r.cycle_id AND s.generation_id=r.generation_id AND s.appearance_revision=r.appearance_revision AND s.original_budget_micro=r.original_budget_micro AND s.source_build_hash=r.source_build_hash AND s.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND s.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND s.original_budget_micro<=(SELECT task_limit_micro FROM tower_autonomy_mandate WHERE id=1)) AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls q WHERE q.cycle_id=r.cycle_id AND q.state IN ('unknown','dispatching')) AND ((r.state='audit' AND NEW.model='muse-spark-1.3') OR (r.state IN ('render-0','render-1','render-2','render-3') AND NEW.model='tool:browser-screenshot' AND NEW.reserved_micro=90000 AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls q WHERE q.model='tool:browser-screenshot' AND julianday(COALESCE(q.completed_at,q.created_at))>julianday('now')-10.0/86400)))))) THEN 1 ELSE RAISE(ABORT,'theme_build_dispatch') END;
END;
CREATE TRIGGER tower_theme_build_review_delete BEFORE DELETE ON tower_theme_build_reviews BEGIN SELECT RAISE(ABORT,'theme_build_permanent'); END;
CREATE TRIGGER tower_theme_build_review_replace BEFORE INSERT ON tower_theme_build_reviews WHEN EXISTS(SELECT 1 FROM tower_theme_build_reviews WHERE id=NEW.id OR extension_id=NEW.extension_id) BEGIN SELECT RAISE(ABORT,'theme_build_permanent'); END;
CREATE TRIGGER tower_theme_build_acceptance_delete BEFORE DELETE ON tower_theme_build_acceptances BEGIN SELECT RAISE(ABORT,'theme_build_permanent'); END;
CREATE TRIGGER tower_theme_build_acceptance_replace BEFORE INSERT ON tower_theme_build_acceptances WHEN EXISTS(SELECT 1 FROM tower_theme_build_acceptances WHERE review_id=NEW.review_id OR (artifact_id=NEW.artifact_id AND target_build_hash=NEW.target_build_hash)) BEGIN SELECT RAISE(ABORT,'theme_build_permanent'); END;
CREATE TRIGGER tower_theme_build_acceptance_update BEFORE UPDATE ON tower_theme_build_acceptances BEGIN SELECT RAISE(ABORT,'theme_build_permanent'); END;
CREATE TRIGGER tower_theme_build_acceptance_guard BEFORE INSERT ON tower_theme_build_acceptances BEGIN
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tower_theme_build_reviews r JOIN tower_theme_artifacts a ON a.id=r.artifact_id WHERE r.id=NEW.review_id AND r.state='publish' AND r.outcome='pass' AND r.lease_until>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND r.extension_id=NEW.extension_id AND r.artifact_id=NEW.artifact_id AND r.target_build_hash=NEW.target_build_hash AND a.sha256=NEW.manifest_hash AND r.generation_id=NEW.generation_id AND r.appearance_revision=NEW.appearance_revision AND EXISTS(SELECT 1 FROM tower_theme_build_source s WHERE s.id=r.extension_id AND s.artifact_id=r.artifact_id AND s.cycle_id=r.cycle_id AND s.generation_id=r.generation_id AND s.appearance_revision=r.appearance_revision AND s.original_budget_micro=r.original_budget_micro AND s.source_build_hash=r.source_build_hash AND s.starts_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND s.ends_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (SELECT enabled FROM tower_autonomy_mandate WHERE id=1)=1 AND s.original_budget_micro<=(SELECT task_limit_micro FROM tower_autonomy_mandate WHERE id=1))) THEN 1 ELSE RAISE(ABORT,'theme_build_acceptance') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tower_theme_build_reviews r JOIN tower_autonomy_calls a ON a.id=json_extract(r.audit_json,'$.callId') JOIN tower_autonomy_calls m ON m.id=json_extract(r.review_json,'$.callId') WHERE r.id=NEW.review_id AND r.locale='en' AND json_extract(r.evidence_json,'$.locale')='en' AND json_extract(r.evidence_json,'$.verified')=1 AND json_extract(r.evidence_json,'$.rendererBuildHash')=r.target_build_hash AND json_extract(r.evidence_json,'$.manifestHash')=NEW.manifest_hash AND json_extract(r.audit_json,'$.manifestHash')=NEW.manifest_hash AND json_extract(r.audit_json,'$.verdict')='PASS' AND json_extract(r.audit_json,'$.rendererBuildHash')=r.target_build_hash AND a.cycle_id=r.cycle_id AND a.state='received' AND a.model='muse-spark-1.3' AND a.purpose='lobby-build-v1:'||r.id||':audit' AND m.cycle_id=r.cycle_id AND m.state='received' AND m.model='muse-spark-1.3' AND m.purpose='lobby-build-v1:'||r.id||':selfreview') THEN 1 ELSE RAISE(ABORT,'theme_build_audit') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tower_theme_build_reviews r WHERE r.id=NEW.review_id AND json_type(r.evidence_json,'$.screenshots')='array' AND json_array_length(r.evidence_json,'$.screenshots')=4 AND (SELECT count(DISTINCT json_extract(value,'$.callId')) FROM json_each(r.evidence_json,'$.screenshots'))=4 AND (SELECT count(*) FROM json_each(r.evidence_json,'$.screenshots') s JOIN tower_autonomy_calls p ON p.id=json_extract(s.value,'$.callId') JOIN tower_autonomy_events d ON d.id='theme-build-render-dispatch:'||p.id WHERE p.cycle_id=r.cycle_id AND p.state='received' AND p.model='tool:browser-screenshot' AND p.actual_micro IS NOT NULL AND p.actual_micro<=p.reserved_micro AND p.purpose='lobby-build-v1:'||r.id||':render-'||s.key AND json_extract(s.value,'$.rendererBuildHash')=r.target_build_hash AND json_extract(s.value,'$.reviewId')=r.id AND json_extract(s.value,'$.index')=CAST(s.key AS INTEGER) AND json_extract(s.value,'$.manifestHash')=NEW.manifest_hash AND json_extract(s.value,'$.scene')=CASE WHEN s.key IN (0,2) THEN 'day' ELSE 'night' END AND json_extract(s.value,'$.viewport')=CASE WHEN s.key IN (0,1) THEN 'desktop' ELSE 'mobile' END AND json_extract(s.value,'$.width')=CASE WHEN s.key IN (0,1) THEN 1280 ELSE 390 END AND json_extract(s.value,'$.height')>=600 AND d.kind='lobby-build-render-dispatched' AND json_extract(d.detail_json,'$.rendererBuildHash')=r.target_build_hash AND json_extract(d.detail_json,'$.reviewId')=r.id AND json_extract(d.detail_json,'$.receiptId')=p.id AND json_extract(d.detail_json,'$.manifestHash')=NEW.manifest_hash)=4 AND NOT EXISTS(SELECT 1 FROM tower_autonomy_calls WHERE cycle_id=r.cycle_id AND state IN ('unknown','dispatching')) AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE cycle_id=r.cycle_id)<=r.original_budget_micro AND (SELECT COALESCE(SUM(COALESCE(actual_micro,reserved_micro)),0) FROM tower_autonomy_calls WHERE billing_day=(SELECT date(native_now,CASE WHEN native_now>='2026-03-08T10:00:00.000Z' THEN '-7 hours' WHEN native_now>=date(substr(native_now,1,4)||'-03-01','weekday 0','+7 days')||'T10:00:00.000Z' AND native_now<date(substr(native_now,1,4)||'-11-01','weekday 0')||'T09:00:00.000Z' THEN '-7 hours' ELSE '-8 hours' END) FROM (SELECT strftime('%Y-%m-%dT%H:%M:%fZ','now') native_now)))<=(SELECT daily_limit_micro FROM tower_autonomy_mandate WHERE id=1)) THEN 1 ELSE RAISE(ABORT,'theme_build_evidence') END;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM tower_theme_build_reviews r WHERE r.id=NEW.review_id AND (SELECT count(DISTINCT s.key) FROM json_each(r.evidence_json,'$.screenshots') s JOIN tower_autonomy_events v ON v.cycle_id=r.cycle_id AND v.kind='lobby-build-rendered' AND json_extract(v.detail_json,'$.reviewId')=r.id AND json_extract(v.detail_json,'$.callId')=json_extract(s.value,'$.callId') WHERE 1=1 AND json_extract(s.value,'$.index')=json_extract(v.detail_json,'$.index') AND json_extract(s.value,'$.scene')=json_extract(v.detail_json,'$.scene') AND json_extract(s.value,'$.viewport')=json_extract(v.detail_json,'$.viewport') AND json_extract(s.value,'$.objectKey')=json_extract(v.detail_json,'$.objectKey') AND json_extract(s.value,'$.sha256')=json_extract(v.detail_json,'$.sha256') AND json_extract(s.value,'$.bytes')=json_extract(v.detail_json,'$.bytes') AND json_extract(s.value,'$.width')=json_extract(v.detail_json,'$.width') AND json_extract(s.value,'$.height')=json_extract(v.detail_json,'$.height') AND json_extract(s.value,'$.manifestHash')=json_extract(v.detail_json,'$.manifestHash') AND json_extract(s.value,'$.htmlHash')=json_extract(v.detail_json,'$.htmlHash') AND json_extract(s.value,'$.rendererBuildHash')=json_extract(v.detail_json,'$.rendererBuildHash') AND length(json_extract(s.value,'$.sha256'))=64 AND json_extract(s.value,'$.sha256') NOT GLOB '*[^0-9a-f]*' AND length(json_extract(s.value,'$.htmlHash'))=64 AND json_extract(s.value,'$.htmlHash') NOT GLOB '*[^0-9a-f]*' AND json_extract(s.value,'$.bytes')>0 AND json_extract(s.value,'$.objectKey') LIKE 'tower-manager-private/lobby-build/%')=4) THEN 1 ELSE RAISE(ABORT,'theme_build_png_provenance') END;
END;
